def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    template = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not template:
        return out
    r0 = min(r for r, c in template)
    c0 = min(c for r, c in template)
    shape = {(r - r0, c - c0) for r, c in template}

    colors = set(v for row in grid for v in row) - {bg, 4}
    for color in colors:
        remaining = {(r, c) for r in range(h) for c in range(w)
                     if grid[r][c] == color}
        initial_count = len(remaining)

        while remaining:
            if len(remaining) == 1 and initial_count > 1:
                break

            placements = set()
            for r, c in remaining:
                for sr, sc in shape:
                    placements.add((r - sr, c - sc))

            best = None
            best_score = -1
            minr = min(r for r, c in remaining)
            minc = min(c for r, c in remaining)
            for top, left in placements:
                covered = {(r, c) for r, c in remaining
                           if (r - top, c - left) in shape}
                score = len(covered)
                key = (score, -abs(top - minr) - abs(left - minc))
                if best is None or key > best_score:
                    best = (top, left, covered)
                    best_score = key

            top, left, covered = best
            if len(covered) < 2 and initial_count > 1:
                break

            for dr, dc in shape:
                r, c = top + dr, left + dc
                if 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                    out[r][c] = color
            remaining -= covered

    return out
